//! agentdeck's HTTP client, generated by progenitor from the daemon's `openapi.json` and
//! checked in. `cargo xtask client` regenerates it.
//!
//! Every daemon request carries a bearer token; [`authenticated`] builds a [`Client`] that
//! sends it. [`daemon::connect`] finds the running daemon, starting it if need be, and
//! [`ws::open`] opens its WebSocket. [`ApiError`] turns a failed call into what the daemon
//! said; [`panes`] and [`instructions`] hold the pane and instruction operations that take more
//! than one call, [`prs`] reads the pull requests as the GUI shows them, and [`settings`] names
//! settings by dotted key.

pub mod daemon;
pub mod error;
pub mod instructions;
pub mod panes;
pub mod prs;
pub mod settings;
pub mod ws;

#[allow(missing_docs, clippy::all, rustdoc::all)]
mod generated;

pub use generated::*;

pub use error::{ApiError, ErrorBody};

/// Why [`authenticated`] couldn't build a client.
#[derive(Debug, thiserror::Error)]
pub enum ConnectError {
    /// The token can't be sent in an HTTP header.
    #[error("the token isn't a valid header value")]
    InvalidToken,
    /// reqwest couldn't build its client.
    #[error("building the HTTP client: {0}")]
    Http(#[from] reqwest::Error),
}

/// A client for the daemon at `baseurl` (`http://127.0.0.1:<port>`) that sends
/// `Authorization: Bearer <token>` on every request.
pub fn authenticated(baseurl: &str, token: &str) -> Result<Client, ConnectError> {
    let mut value = reqwest::header::HeaderValue::from_str(&format!("Bearer {token}"))
        .map_err(|_| ConnectError::InvalidToken)?;
    value.set_sensitive(true);
    let mut headers = reqwest::header::HeaderMap::new();
    headers.insert(reqwest::header::AUTHORIZATION, value);
    let http = reqwest::Client::builder()
        .default_headers(headers)
        .build()?;
    Ok(Client::new_with_client(baseurl, http))
}
